// Update handles messages.
func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case sharedcomponents.ConfirmModalYesMsg:
		return m.handleBackendConfirmed()

	case sharedcomponents.ConfirmModalNoMsg:
		return m.handleBackendRejected()

	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.resizeInput()
		m.keepFocusVisible()
		return m, nil

	// The router's detection (§3.86), for the tools tab's headings.
	case shared.ScanToolsMsg:
		m.tools = msg.Report
		return m, nil

	case filebrowser.PathPickedMsg:
		return m.handlePathPicked(msg)

	case MCPCommandCopiedMsg:
		return m.handleMCPCommandCopied(msg)

	case saveFailedMsg:
		log.Printf("ERROR [configuration] save: %v", msg.err)
		return m, m.footer.Error("Failed to save — check logs")

	case tea.KeyPressMsg:
		if m.confirmModal != nil {
			var cmd tea.Cmd
			m.confirmModal, cmd = m.confirmModal.Update(msg)
			return m, cmd
		}
		next, cmd := m.handleKey(msg)
		if updated, ok := next.(Model); ok {
			updated.keepFocusVisible()
			next = updated
		}
		return next, cmd

// all come from it. The router keeps this view on a save (that is what stops a
// save throwing away the cursor), so nothing else would rebuild it.
func (m Model) adoptForge(forgeType string) Model {
	m.config.Forge.Type = forgeType

	shape := forge.ShapeFor(forgeType)
	if !shape.AllowsVisibility(m.config.Forge.DefaultVisibility) {
